/**
 * Public multipart form. Creates a pending request for owner review (not a confirmed booking). Optional photos (JPEG/PNG/WebP, max 5, 5MB each) stored in R2.
 * @summary Submit a service request
 */
export const createServiceRequest = async (serviceRequestInput: ServiceRequestInput, options?: Parameters<typeof customFetch>[1]): Promise<ServiceRequest> => {
    const formData = new FormData();
formData.append(`name`, serviceRequestInput.name);
formData.append(`email`, serviceRequestInput.email);
formData.append(`phone`, serviceRequestInput.phone);
formData.append(`service`, serviceRequestInput.service);
formData.append(`description`, serviceRequestInput.description);
if(serviceRequestInput.urgency !== undefined) {
 formData.append(`urgency`, serviceRequestInput.urgency);
 }
if(serviceRequestInput.preferredDate !== undefined) {
 formData.append(`preferredDate`, serviceRequestInput.preferredDate);
 }
if(serviceRequestInput.preferredTime !== undefined) {
 formData.append(`preferredTime`, serviceRequestInput.preferredTime);
 }
if(serviceRequestInput.photos !== undefined) {
 serviceRequestInput.photos.forEach(value => formData.append(`photos`, value));
 }
if(serviceRequestInput.videos !== undefined) {
 serviceRequestInput.videos.forEach(value => formData.append(`videos`, value));
 }
if(serviceRequestInput.jobStreet !== undefined) {
 formData.append(`jobStreet`, serviceRequestInput.jobStreet);
 }
if(serviceRequestInput.jobCity !== undefined) {
 formData.append(`jobCity`, serviceRequestInput.jobCity);
 }
if(serviceRequestInput.jobZip !== undefined) {
 formData.append(`jobZip`, serviceRequestInput.jobZip);
 }

  return customFetch<ServiceRequest>(getCreateServiceRequestUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





